from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = None

    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            sep = ("row", r)
            break
    if sep is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                sep = ("col", c)
                break
    if sep is None:
        return grid

    axis, i = sep
    if axis == "row":
        source, other = grid[:i], grid[i + 1:]
    else:
        source = [row[i + 1:] for row in grid]
        other = [row[:i] for row in grid]

    counts = Counter(x for row in source for x in row)
    background = counts.most_common(1)[0][0]
    foreground = next((x for x, _ in counts.most_common() if x != background), background)
    other_colors = {x for row in other for x in row}

    out_bg = foreground if foreground in other_colors else background
    return [[3 if x != background else out_bg for x in row] for row in source]
